fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    assert!(
        arr1.len() == arr2.len(),
        "Input arrays must have the same length"
    );

    let mut result = Vec::with_capacity(arr1.len());
    for i in 0..arr1.len() {
        let divisor = arr2[i];
        assert!(divisor != 0, "Second array must not contain zeros");

        // Integer division for u32 is truncating toward zero.
        let q = arr1[i] / divisor;

        // Assumption says it fits in i32; enforce it defensively.
        assert!(q <= i32::MAX as u32, "Quotient does not fit in i32 range");

        result.push(q);
    }
    result
}